// =====================================================================
//  Sprite atlases
//
//  atlas_party.png and atlas_outside.png are generated by tools/*.mjs from
//  the raw art sheets: the frames we use, backgrounds keyed out, packed
//  into one image. Miner_*.png and the caves sheet ship as clean grids and
//  are indexed directly.
// =====================================================================
import { ctx } from "./gfx.js";

export const ATLAS = {
    party: {
        // cw/ch/ground are reported by tools/extract-sprites.mjs — keep in sync.
        src: "assets/atlas_party.png", cw: 51, ch: 63, ground: 61, img: null, white: null, ready: false,
        rows:   { Mage: 0, Cleric: 1, Thief: 2, husk: 3 },
        frames: { Mage: 6, Cleric: 6, Thief: 6, husk: 3 },   // columns 0..5 = idle/walk
        attack:  { first: 6, count: 2, duration: 0.22 },     // columns 6..7, matches Hero.AttackAnim
        ability: { col: 8, duration: 0.45 },                 // column 8, matches Hero.AbilityAnim
    },
    ores: { src: "assets/Miner_Ores.png", cw: 128, ch: 128, img: null, ready: false },
    deco: { src: "assets/Miner_Decorations.png", cw: 128, ch: 128, img: null, ready: false },
    // 32px grid (51x48 tiles) — established from the sheet's own transparent
    // cut-outs, which land exactly on 32px boundaries.
    caves: { src: "assets/Caves/MainLev2.0.png", cw: 32, ch: 32, img: null, ready: false },
    // Stage 1. `outTiles` is the raw contact sheet, sampled for terrain;
    // `outside` is the packed prop atlas, addressed by name.
    outTiles: { src: "assets/Outside/outside_tiles.png", cw: 32, ch: 32, img: null, ready: false },
    outside:  { src: "assets/Outside/atlas_outside.png", cw: 32, ch: 32, img: null, ready: false },
    // Villagers and creatures, packed by tools/extract-chars.mjs.
    chars:    { src: "assets/Outside/atlas_chars.png", cw: 32, ch: 32, img: null, ready: false },
};

let outsideFrames = null;                     // { kind: [{x,y,w,h}, ...] }
let charFrames = null;
export const getOutsideFrames = () => outsideFrames;
export const getCharFrames = () => charFrames;

// An all-white copy of an atlas, used to flash a sprite when it takes a hit.
function makeWhiteMask(img) {
    const c = document.createElement("canvas");
    c.width = img.width; c.height = img.height;
    const g = c.getContext("2d");
    g.drawImage(img, 0, 0);
    g.globalCompositeOperation = "source-in";
    g.fillStyle = "#ffffff";
    g.fillRect(0, 0, c.width, c.height);
    return c;
}

export function loadAtlases(onFramesReady) {
    for (const a of Object.values(ATLAS)) {
        if (a.img) continue;
        const im = new Image();
        im.onload = () => {
            a.ready = true;
            if ("white" in a) a.white = makeWhiteMask(im);   // only atlases that flash
        };
        im.onerror = () => console.error("sprite atlas failed to load:", a.src);
        im.src = a.src;
        a.img = im;
    }
    if (!outsideFrames)
        fetch("assets/Outside/atlas_outside.json")
            .then(r => r.json())
            .then(j => { outsideFrames = j; onFramesReady?.(); })
            .catch(e => console.error("outside atlas frame table failed:", e));
    if (!charFrames)
        fetch("assets/Outside/atlas_chars.json")
            .then(r => r.json())
            .then(j => { charFrames = j; })
            .catch(e => console.error("character atlas frame table failed:", e));
}

// Per-entity animation clocks. The engine sends positions, not a "moving" flag,
// so the stride is advanced by distance actually travelled — the walk cycle then
// stays in step at any speed and settles into a slow sway when standing still.
const animState = new Map();
export function animFrame(key, e, count, stride = 7) {
    let a = animState.get(key);
    if (!a) { a = { p: 0, x: e.x, y: e.y }; animState.set(key, a); }
    const d = Math.hypot(e.x - a.x, e.y - a.y);
    a.x = e.x; a.y = e.y;
    a.p += d > 0.03 ? d / stride : 0.04;
    return Math.floor(a.p) % count;
}

// Blits one cell, horizontally centred on cx with the atlas ground line landing
// on footY. Aligning the ground line rather than the cell bottom is what lets a
// pose whose effect hangs below the boots sit on the floor without lifting the
// hero off it.
export function drawSprite(a, col, row, cx, footY, scale, flip, alpha, flash) {
    const dw = a.cw * scale, dh = a.ch * scale;
    const top = footY - (a.ground ?? a.ch) * scale;
    ctx.save();
    ctx.imageSmoothingEnabled = false;      // keep the pixel art crisp
    ctx.globalAlpha = alpha;
    ctx.translate(cx, 0);
    if (flip) ctx.scale(-1, 1);
    ctx.drawImage(a.img, col * a.cw, row * a.ch, a.cw, a.ch, -dw / 2, top, dw, dh);
    if (flash > 0 && a.white) {
        ctx.globalAlpha = Math.min(0.85, flash * 6) * alpha;
        ctx.drawImage(a.white, col * a.cw, row * a.ch, a.cw, a.ch, -dw / 2, top, dw, dh);
    }
    ctx.restore();
}
